package com.kitchenai.recipe;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity public class Recipe { @Id private UUID id; private UUID userId; private String title; @Column(columnDefinition="TEXT") private String description; private String productType; private int servings; private int preparationTime; private int cookingTime; @Column(columnDefinition="TEXT") private String ingredientsJson; @Column(columnDefinition="TEXT") private String stagesJson; private Instant createdAt;
 public Recipe(){} public Recipe(UUID userId,String title,String description,String productType,int servings,int prep,int cook,String ingredients,String stages){id=UUID.randomUUID();this.userId=userId;this.title=title;this.description=description;this.productType=productType;this.servings=servings;preparationTime=prep;cookingTime=cook;ingredientsJson=ingredients;stagesJson=stages;createdAt=Instant.now();} public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getTitle(){return title;} public String getDescription(){return description;} public String getProductType(){return productType;} public int getServings(){return servings;} public int getPreparationTime(){return preparationTime;} public int getCookingTime(){return cookingTime;} public String getIngredientsJson(){return ingredientsJson;} public String getStagesJson(){return stagesJson;} public Instant getCreatedAt(){return createdAt;}}
